#include "rcc.h"
#include "gpio.h"
#include "timer.h"
#include "usart.h"
#include "i2c.h"

int main (void)
{
	uint32_t data_rx = 0;

	rcc_pllclk_init();

	gpio_init();
	/* Reset led */
	GPIOA->BSRR = (3UL << 9U);

	timer2_init();
	usart_pins_init();
	usart_frame_config();

	while (1)
	{	
		data_rx = usart_receive_char();

		switch (data_rx)
		{
		case 'S':
			GPIOA->BRR = (3UL << 9U);
			usart_transmit_string("- Turn on the led PA9 & PA10\n");	
			break;
		
		case 'T':
			GPIOA->BSRR = (3UL << 9U);
			usart_transmit_string("- Turn off the led PA9 & PA10\n");
			break;

		default:
			usart_transmit_string("- Please try again!\n");
			break;
		}

	}
}
